-- 1. Tables (un document JSON par ligne, comme dans la version Claude)
create table if not exists public.domaines   (id text primary key, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.formations (id text primary key, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.profils    (id text primary key, data jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
-- Personnes autorisées à modifier le contenu (adresse e-mail du compte de connexion)
create table if not exists public.editeurs   (email text primary key);

-- 2. Règles d'accès : tout le monde lit, seuls les éditeurs connectés modifient
alter table public.domaines   enable row level security;
alter table public.formations enable row level security;
alter table public.profils    enable row level security;
alter table public.editeurs   enable row level security;

create or replace function public.est_editeur() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.editeurs e where lower(e.email) = lower(coalesce(auth.jwt() ->> 'email', '')));
$$;
revoke all on function public.est_editeur() from public;
grant execute on function public.est_editeur() to anon, authenticated;

drop policy if exists "lecture publique" on public.domaines;
create policy "lecture publique" on public.domaines for select to anon, authenticated using (true);
drop policy if exists "ecriture editeurs" on public.domaines;
create policy "ecriture editeurs" on public.domaines for all to authenticated using (public.est_editeur()) with check (public.est_editeur());
grant select on public.domaines to anon, authenticated;
grant insert, update, delete on public.domaines to authenticated;

drop policy if exists "lecture publique" on public.formations;
create policy "lecture publique" on public.formations for select to anon, authenticated using (true);
drop policy if exists "ecriture editeurs" on public.formations;
create policy "ecriture editeurs" on public.formations for all to authenticated using (public.est_editeur()) with check (public.est_editeur());
grant select on public.formations to anon, authenticated;
grant insert, update, delete on public.formations to authenticated;

drop policy if exists "lecture publique" on public.profils;
create policy "lecture publique" on public.profils for select to anon, authenticated using (true);
drop policy if exists "ecriture editeurs" on public.profils;
create policy "ecriture editeurs" on public.profils for all to authenticated using (public.est_editeur()) with check (public.est_editeur());
grant select on public.profils to anon, authenticated;
grant insert, update, delete on public.profils to authenticated;

drop policy if exists "editeur se reconnait" on public.editeurs;
create policy "editeur se reconnait" on public.editeurs for select to authenticated using (lower(email) = lower(coalesce(auth.jwt() ->> 'email', '')));
grant select on public.editeurs to authenticated;

-- 3. Éditrice autorisée (changez l'adresse si vous vous connectez avec une autre)

-- 4. Contenu actuel de l'application



-- Vérification : doit afficher 12, 35 et le nombre de profils
select (select count(*) from public.domaines) as domaines, (select count(*) from public.formations) as formations, (select count(*) from public.profils) as profils;
